import math

def build_agent(sandbox):
    # Create a central hull with sufficient buoyancy and mass
    hull = sandbox.add_beam(x=5.0, y=1.5, width=1.5, height=1.0, density=40.0)
    hull.userData = {'type': 'hull', 'width': 1.5, 'height': 1.0}

    # Add two floats on the sides for enhanced buoyancy (submerged at y=1.5)
    float_left = sandbox.add_beam(x=3.5, y=1.5, width=2.0, height=1.5, density=20.0)
    float_left.userData = {'type': 'float', 'width': 2.0, 'height': 1.5}

    float_right = sandbox.add_beam(x=6.5, y=1.5, width=2.0, height=1.5, density=20.0)
    float_right.userData = {'type': 'float', 'width': 2.0, 'height': 1.5}

    # Connect hull to floats with rigid joints
    sandbox.add_joint(hull, float_left, (3.5, 1.5), type='rigid')
    sandbox.add_joint(hull, float_right, (6.5, 1.5), type='rigid')

    # Add two paddles for propulsion with upward angle for lift
    paddle_left = sandbox.add_beam(x=3.5, y=1.5, width=0.5, height=0.3, density=50.0, angle=math.pi/6)
    paddle_left.userData = {'type': 'paddle', 'width': 0.5, 'height': 0.3, 'last_used': -1000, 'angle': math.pi/6}

    paddle_right = sandbox.add_beam(x=6.5, y=1.5, width=0.5, height=0.3, density=50.0, angle=math.pi/6)
    paddle_right.userData = {'type': 'paddle', 'width': 0.5, 'height': 0.3, 'last_used': -1000, 'angle': math.pi/6}

    # Connect paddles to hull with rigid joints
    sandbox.add_joint(hull, paddle_left, (3.5, 1.5), type='rigid')
    sandbox.add_joint(hull, paddle_right, (6.5, 1.5), type='rigid')

    # Set material properties for buoyancy and energy dissipation
    for body in [hull, float_left, float_right, paddle_left, paddle_right]:
        sandbox.set_material_properties(body, restitution=0.1)

    return hull


def agent_action(sandbox, agent_body, step_count):
    if agent_body is None or not agent_body.active:
        return

    # Calculate front x and y based on hull's position and angle
    hull_position = agent_body.position
    hull_angle = agent_body.angle
    hull_width = agent_body.userData.get('width', 1.5)
    hull_height = agent_body.userData.get('height', 1.0)

    # Correct front position calculation using hull's dimensions and rotation
    front_x = hull_position.x + (hull_width / 2) * math.cos(hull_angle) - (hull_height / 2) * math.sin(hull_angle)
    front_y = hull_position.y + (hull_width / 2) * math.sin(hull_angle) + (hull_height / 2) * math.cos(hull_angle)

    target_x = 26.0
    if front_x >= target_x + 0.1:
        # Stop all motion
        for b in sandbox.bodies:
            if b.userData and b.userData.get('type') == 'paddle':
                sandbox.apply_force(b, 0.0, 0.0, step_count=step_count)
        return

    # Identify all paddles for control
    paddles = [b for b in sandbox.bodies if b.userData and b.userData.get('type') == 'paddle']
    left_paddle = next((b for b in paddles if b.userData.get('width') == 0.5 and b.position.x == 3.5), None)
    right_paddle = next((b for b in paddles if b.userData.get('width') == 0.5 and b.position.x == 6.5), None)

    # Check if in deep channel (reduced buoyancy zone)
    in_danger_zone = (16.5 <= front_x <= 19.5)

    # Apply propulsion with cooldown and joint safety
    for paddle in paddles:
        last_used = paddle.userData.get('last_used', -1000)
        if step_count - last_used > 18:  # 18-step cooldown
            # Calculate propulsion force within joint strength limit
            fx = 0.0
            fy = 0.0

            # Adjust force based on current velocity to manage speed
            vx = agent_body.linearVelocity.x
            if in_danger_zone:
                # Apply maximum force with upward component to counteract reduced buoyancy
                paddle_angle = paddle.userData.get('angle', 0.0)
                fx = -520.0 * math.cos(paddle_angle)
                fy = 520.0 * math.sin(paddle_angle)
            else:
                # Default to max force with forward component
                fx = -520.0
                # Adjust based on velocity
                if vx > 1.8:
                    fx *= 0.1  # Reduce thrust when moving too fast
                elif vx > 1.0:
                    fx *= 0.4  # Moderate thrust for stability

            # Apply force to paddle
            sandbox.apply_force(paddle, fx, fy, step_count=step_count)
            paddle.userData['last_used'] = step_count

    # Obstacle avoidance logic with steering
    pillars = [(14.0, 'left'), (17.0, 'mid'), (20.0, 'right')]
    for pillar_x, pillar_name in pillars:
        distance = abs(front_x - pillar_x)
        if distance < 2.0:
            # Apply differential force to avoid the pillar
            if pillar_name == 'left':
                # Turn right
                for paddle in paddles:
                    last_used = paddle.userData.get('last_used', -1000)
                    if step_count - last_used > 18:
                        if paddle == right_paddle:
                            fx = -520.0
                        else:
                            fx = 0.0
                        sandbox.apply_force(paddle, fx, 0.0, step_count=step_count)
                        paddle.userData['last_used'] = step_count
            elif pillar_name == 'mid':
                # Turn slightly left or right based on position
                if front_x < pillar_x:
                    # Turn right
                    for paddle in paddles:
                        last_used = paddle.userData.get('last_used', -1000)
                        if step_count - last_used > 18:
                            if paddle == right_paddle:
                                fx = -520.0
                            else:
                                fx = 0.0
                            sandbox.apply_force(paddle, fx, 0.0, step_count=step_count)
                            paddle.userData['last_used'] = step_count
                else:
                    # Turn left
                    for paddle in paddles:
                        last_used = paddle.userData.get('last_used', -1000)
                        if step_count - last_used > 18:
                            if paddle == left_paddle:
                                fx = -520.0
                            else:
                                fx = 0.0
                            sandbox.apply_force(paddle, fx, 0.0, step_count=step_count)
                            paddle.userData['last_used'] = step_count
            elif pillar_name == 'right':
                # Turn left
                for paddle in paddles:
                    last_used = paddle.userData.get('last_used', -1000)
                    if step_count - last_used > 18:
                        if paddle == left_paddle:
                            fx = -520.0
                        else:
                            fx = 0.0
                        sandbox.apply_force(paddle, fx, 0.0, step_count=step_count)
                        paddle.userData['last_used'] = step_count

    # Check for sinking based on all components' lowest y-coordinate
    lowest_y = float('inf')
    for body in sandbox.bodies:
        if not body.userData:
            continue
        if body.userData.get('type') in ['hull', 'float', 'paddle']:
            body_position = body.position
            body_angle = body.angle
            width = body.userData.get('width', 1.5)
            height = body.userData.get('height', 1.0)
            # Calculate lowest y-coordinate of the body
            current_lowest = body_position.y - (height / 2) * math.cos(body_angle) - (width / 2) * math.sin(body_angle)
            if current_lowest < lowest_y:
                lowest_y = current_lowest

    if lowest_y < -0.5:
        # Stop all paddles
        for b in sandbox.bodies:
            if b.userData and b.userData.get('type') == 'paddle':
                sandbox.apply_force(b, 0.0, 0.0, step_count=step_count)

